//! Task Scheduler (`/api/v1/scheduler/...`).
//!
//! Configuration key `scheduler` ([`SchedulerConfig`]): every task becomes persistent systemd
//! units generated by rynasd (`/etc/systemd/system/rynas-task-<id>.service` and, with a
//! trigger, `.timer`). Writes stage pending changes; `POST /api/v1/config/apply` applies them.
//! Each run is recorded with its result and the tail of its output (journal).

use serde::{Deserialize, Serialize};

pub use rynas_schedule::Recurrence;

use crate::PendingOp;

fn default_true() -> bool {
    true
}

/// The `scheduler` configuration key.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SchedulerConfig {
    #[serde(default)]
    pub tasks: Vec<ScheduledTask>,
}

/// One scheduled task.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ScheduledTask {
    /// `[a-z0-9][a-z0-9-]{0,47}`, unique; the units are `rynas-task-<id>.*`. Cannot change.
    pub id: String,
    /// Display name.
    #[serde(default)]
    pub name: String,
    #[serde(default)]
    pub description: String,
    /// A disabled task keeps its units but its timer is stopped (run now still works).
    #[serde(default = "default_true")]
    pub enabled: bool,
    pub action: TaskAction,
    pub trigger: TaskTrigger,
    /// `RuntimeMaxSec`: the run is stopped (whole cgroup) after this many seconds.
    #[serde(default)]
    pub timeout_s: Option<u64>,
    /// `Nice=` (-20..=19); `None`: 10 for user tasks, 0 for internal ones.
    #[serde(default)]
    pub nice: Option<i32>,
    /// `IOWeight=` (1..=10000); `None`: systemd's default (100).
    #[serde(default)]
    pub io_weight: Option<u32>,
    #[serde(default)]
    pub notify: NotifyPolicy,
    /// Attach the output (last 256 KiB) to the notification.
    #[serde(default)]
    pub notify_output: bool,
    /// Who owns the task: the user (Task Scheduler page) or a feature that creates, changes
    /// and removes it with its own settings. Absent in documents written before owners:
    /// [`ScheduledTask::migrate`] derives it from the action.
    #[serde(default, skip_serializing_if = "TaskOwner::is_user")]
    pub owner: TaskOwner,
    /// Missed runs, overlap, random delay, retry, notification rules. Its defaults are the
    /// behaviour of tasks written before run policies (see [`ScheduledTask::effective_policy`]).
    #[serde(default, skip_serializing_if = "RunPolicy::is_empty")]
    pub policy: RunPolicy,
}

impl ScheduledTask {
    /// Brings a task written by an older rynas to the current model; idempotent, and a task
    /// already in the current model is left as it is:
    ///
    /// - `owner` always from the action ([`TaskOwner::of_action`]): never what a client sent,
    ///   so a user task cannot claim a feature's locks and a feature's task cannot shed them;
    /// - `policy.missed` and `policy.jitter_s` from a calendar trigger's `persistent` and
    ///   `randomized_delay_s` when absent; then the trigger's two fields mirror the policy
    ///   (the policy is the reference, the trigger fields stay readable for older clients).
    ///   A write that gives both must make them agree (`rynas_scheduler::normalize_task`
    ///   refuses a disagreement instead of letting the policy win silently).
    ///
    /// The units of a migrated task are the units of the task before (golden tests in
    /// `rynas-scheduler`).
    pub fn migrate(&mut self) {
        self.owner = TaskOwner::of_action(&self.action);
        if let TaskTrigger::Calendar {
            persistent,
            randomized_delay_s,
            ..
        } = &mut self.trigger
        {
            let missed = *self.policy.missed.get_or_insert(if *persistent {
                MissedPolicy::RunOnce { within_h: None }
            } else {
                MissedPolicy::Skip
            });
            let jitter = *self.policy.jitter_s.get_or_insert(*randomized_delay_s);
            *persistent = missed.catches_up();
            *randomized_delay_s = jitter;
        }
    }

    /// The policy that applies, with the defaults filled in: catch-up and random delay from
    /// the trigger when the policy has none, overlap `queue` (systemd starts a service once
    /// more after a run its time fell into: the behaviour before the gate), retry by kind ([`Retry::default_for`]), notification level
    /// from `notify`.
    pub fn effective_policy(&self) -> EffectivePolicy {
        let (persistent, delay) = match &self.trigger {
            TaskTrigger::Calendar {
                persistent,
                randomized_delay_s,
                ..
            } => (*persistent, *randomized_delay_s),
            // a preset is a calendar: catch-up on unless the policy says otherwise
            TaskTrigger::Recurrence { .. } => (true, 0),
            _ => (false, 0),
        };
        let calendar = matches!(
            self.trigger,
            TaskTrigger::Calendar { .. } | TaskTrigger::Recurrence { .. }
        );
        EffectivePolicy {
            missed: match self.policy.missed {
                Some(m) if calendar => m,
                _ if calendar && persistent => MissedPolicy::RunOnce { within_h: None },
                _ => MissedPolicy::Skip,
            },
            jitter_s: self.policy.jitter_s.unwrap_or(delay),
            overlap: self.policy.overlap.unwrap_or_default(),
            retry: self
                .policy
                .retry
                .unwrap_or_else(|| Retry::default_for(&self.action)),
            notify: self.notify,
            rules: self.policy.notify,
        }
    }
}

/// Who owns a task.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum TaskOwner {
    /// Made on the Task Scheduler page (or through its API).
    #[default]
    User,
    /// Created, changed and removed by a feature with its own settings (`key`: the job, the
    /// replica `job/target`, the power rule, the deduplication volume).
    Feature { feature: OwnerFeature, key: String },
}

/// The features that own tasks.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum OwnerFeature {
    Snapshots,
    Replication,
    Backup,
    Power,
    Dedup,
}

/// Parts of a task its owner decides: the Task Scheduler page shows them read-only.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LockedField {
    Action,
    Schedule,
    /// Catch-up of missed runs (a shutdown or a deduplication run never catches up).
    Missed,
}

impl TaskOwner {
    pub fn is_user(&self) -> bool {
        *self == TaskOwner::User
    }

    /// The owner of a task with this action: the feature that creates such tasks, else the
    /// user.
    pub fn of_action(a: &TaskAction) -> TaskOwner {
        let (feature, key) = match a {
            TaskAction::Snapshot { job } => (OwnerFeature::Snapshots, job.clone()),
            TaskAction::Replicate { job, target } => {
                (OwnerFeature::Replication, format!("{job}/{target}"))
            }
            TaskAction::Backup { job } => (OwnerFeature::Backup, job.clone()),
            TaskAction::PowerShutdown { rule } => (OwnerFeature::Power, rule.clone()),
            TaskAction::Dedup { volume } => (OwnerFeature::Dedup, volume.clone()),
            _ => return TaskOwner::User,
        };
        TaskOwner::Feature { feature, key }
    }

    /// What the owner decides.
    pub fn locked(&self) -> &'static [LockedField] {
        match self {
            TaskOwner::User => &[],
            TaskOwner::Feature {
                feature: OwnerFeature::Power | OwnerFeature::Dedup,
                ..
            } => &[
                LockedField::Action,
                LockedField::Schedule,
                LockedField::Missed,
            ],
            TaskOwner::Feature { .. } => &[LockedField::Action, LockedField::Schedule],
        }
    }
}

/// How a task runs beyond its trigger. Every field is optional: absent = the default of the
/// task's kind, which is what rynas did before run policies.
///
/// `missed` and `jitter_s` are the timer's `Persistent=` and `RandomizedDelaySec=`; the
/// scheduling gate (`ExecCondition=` of every task unit) enforces the catch-up deadline, the
/// pauses and `overlap`; rynasd arms `retry` after a failed scheduled run. The notification
/// rules other than `on_missed` are stored for a later release.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct RunPolicy {
    /// A run missed while the NAS was off.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub missed: Option<MissedPolicy>,
    /// Random delay of each start (`RandomizedDelaySec=`), at most one day.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub jitter_s: Option<u32>,
    /// A start while the previous run is still going.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub overlap: Option<Overlap>,
    /// Retry of a failed run.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub retry: Option<Retry>,
    /// When to notify, on top of the task's `notify` level.
    #[serde(default, skip_serializing_if = "NotifyRules::is_default")]
    pub notify: NotifyRules,
}

impl RunPolicy {
    pub fn is_empty(&self) -> bool {
        *self == RunPolicy::default()
    }
}

/// A run missed while the NAS was off.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum MissedPolicy {
    /// Not caught up.
    Skip,
    /// Caught up once at the next boot (`Persistent=`); with `within_h`, only when the boot
    /// comes at most that many hours after the missed time.
    RunOnce {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        within_h: Option<u32>,
    },
}

impl MissedPolicy {
    pub fn catches_up(self) -> bool {
        matches!(self, MissedPolicy::RunOnce { .. })
    }
}

/// A start while the previous run is still going.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum Overlap {
    /// The new start is dropped and recorded as `overlap`. (A timer whose time comes while
    /// its service runs starts it once more right after the run ends: the gate skips that
    /// start.) Stored explicitly on every task created on the Task Scheduler page since S2.
    Skip,
    /// The new run waits for the running one and starts when it ends (once, however many
    /// times came meanwhile). The default of a task without a stored overlap: what systemd
    /// did before the gate, so an upgrade changes no task's behaviour.
    #[default]
    Queue,
    /// The running one is stopped, the new one starts (checked every few seconds).
    Replace,
}

/// Retry of a failed run.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Retry {
    /// Further attempts after a failure; 0 = none.
    pub attempts: u8,
    /// Wait before the first retry.
    pub delay_s: u32,
    /// Each wait doubles the one before, up to `max_delay_s`.
    #[serde(default = "default_true")]
    pub backoff: bool,
    #[serde(default)]
    pub max_delay_s: u32,
}

impl Retry {
    pub const NONE: Retry = Retry {
        attempts: 0,
        delay_s: 0,
        backoff: false,
        max_delay_s: 0,
    };
    /// Backups and replications: a network or a target that is briefly away should not cost
    /// a whole day (owner decision on the unified scheduling).
    pub const TRANSFER: Retry = Retry {
        attempts: 3,
        delay_s: 600,
        backoff: true,
        max_delay_s: 3600,
    };

    /// The default of a kind of task.
    pub fn default_for(a: &TaskAction) -> Retry {
        match a {
            TaskAction::Backup { .. } | TaskAction::Replicate { .. } => Retry::TRANSFER,
            _ => Retry::NONE,
        }
    }
}

/// Notification rules on top of the task's `notify` level.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct NotifyRules {
    /// Notify a failure only after this many failed runs in a row (1 = every failure).
    #[serde(default = "default_one")]
    pub after_failures: u32,
    /// Notify the first success after failures.
    #[serde(default)]
    pub on_recovery: bool,
    /// Notify a run that was missed and not caught up.
    #[serde(default)]
    pub on_missed: bool,
}

fn default_one() -> u32 {
    1
}

impl Default for NotifyRules {
    fn default() -> Self {
        NotifyRules {
            after_failures: 1,
            on_recovery: false,
            on_missed: false,
        }
    }
}

impl NotifyRules {
    pub fn is_default(&self) -> bool {
        *self == NotifyRules::default()
    }
}

/// [`RunPolicy`] with every default filled in ([`ScheduledTask::effective_policy`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct EffectivePolicy {
    pub missed: MissedPolicy,
    pub jitter_s: u32,
    pub overlap: Overlap,
    pub retry: Retry,
    pub notify: NotifyPolicy,
    pub rules: NotifyRules,
}

/// What a task runs. User actions (`command`, `script`) run as `user`; internal actions run
/// as a rynasd task (UPID, task panel) started by `rynasctl job run <id>`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum TaskAction {
    /// A shell command line (`/bin/sh`).
    Command {
        command: String,
        /// `root` (administrators only) or a local user (uid 1000..=59999).
        #[serde(default = "default_root")]
        user: String,
    },
    /// A script stored by rynas (`/var/lib/rynas/tasks/<id>/run`, root:root 0700); the
    /// interpreter comes from its `#!` line (default `/bin/sh`). It reads the script on its
    /// standard input, so the script itself gets none.
    Script {
        script: String,
        #[serde(default = "default_root")]
        user: String,
    },
    /// Snapshot job (`/api/v1/snapshots/jobs`): `btrbk run` with the job's configuration.
    Snapshot { job: String },
    /// Replica target with its own schedule (`/api/v1/snapshots/replication`): btrbk sends
    /// the job's missing snapshots to the target and applies the target's retention.
    Replicate { job: String, target: String },
    /// `btrfs scrub` of the filesystem mounted at `filesystem`.
    Scrub { filesystem: String },
    /// SMART self-test of a disk (`sda`, `nvme0n1`).
    SmartTest {
        disk: String,
        #[serde(default)]
        test: SmartTestKind,
    },
    /// `#recycle` cleanup of one share, or of every share with a recycle bin.
    RecycleCleanup {
        #[serde(default)]
        share: Option<String>,
        /// Override of the share's retention.
        #[serde(default)]
        days: Option<u32>,
    },
    /// Scheduled shutdown of a power schedule rule (`/api/v1/power/schedule`): checks, then
    /// a clean poweroff. Runs `rynasctl power scheduled-shutdown <rule>`; created, changed
    /// and removed with its rule.
    PowerShutdown { rule: String },
    /// Backup job (`/api/v1/backup/restic/jobs`): backup, retention and maintenance of its
    /// repository by `rynas-backup-worker`; created, changed and removed with its job.
    Backup { job: String },
    /// Deduplication job of a filesystem (`/api/v1/storage/dedup`, key: a volume label or
    /// `uuid.<uuid>`): fires at the start of its window blocks, runs until the block ends;
    /// created, changed and removed with the job's settings.
    Dedup { volume: String },
}

fn default_root() -> String {
    "root".into()
}

impl TaskAction {
    /// Internal actions run inside rynasd; their command cannot be edited.
    pub fn is_internal(&self) -> bool {
        !matches!(self, TaskAction::Command { .. } | TaskAction::Script { .. })
    }

    /// The user a user action runs as.
    pub fn user(&self) -> Option<&str> {
        match self {
            TaskAction::Command { user, .. } | TaskAction::Script { user, .. } => Some(user),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum SmartTestKind {
    #[default]
    Short,
    Long,
}

/// When a task runs.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum TaskTrigger {
    /// systemd calendar event (`OnCalendar=`), e.g. `hourly`, `Mon..Fri 02:30`. A request may
    /// give `cron` instead (`0 4 * * *`): it is converted and stored as `on_calendar`.
    Calendar {
        #[serde(default)]
        on_calendar: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        cron: Option<String>,
        /// `Persistent=`: a run missed while the NAS was off happens at the next boot.
        #[serde(default = "default_true")]
        persistent: bool,
        /// `RandomizedDelaySec=`.
        #[serde(default)]
        randomized_delay_s: u32,
    },
    /// After every boot (`OnBootSec=`), `delay_s` seconds after systemd started.
    Boot {
        #[serde(default = "default_boot_delay")]
        delay_s: u32,
    },
    /// No timer: run now only.
    Manual,
    /// One of the schedule editor's presets. The Task Scheduler stores it as the `Calendar`
    /// of its expression (catch-up and random delay from the run policy), which
    /// `Recurrence::from_calendar` recognizes again: the stored text is always the one
    /// systemd uses.
    Recurrence { recurrence: Recurrence },
    /// Every `hours` hours counted from the last successful run (anacron-like), the first one
    /// `after_boot_min` minutes after boot at the earliest. Not run by the Task Scheduler yet:
    /// a task with it is refused.
    Interval {
        hours: u32,
        #[serde(default)]
        after_boot_min: u32,
    },
    /// At the start of every block of a weekly window (168 characters `0`/`1`, Sunday first,
    /// `window[day * 24 + hour]`, like the other weekly grids); with `stop_at_end` the run is
    /// stopped at the end of its block. Not run by the Task Scheduler yet: a task with it is
    /// refused.
    Window {
        window: String,
        #[serde(default)]
        stop_at_end: bool,
    },
    /// After another task finished (only after a success with `only_on_success`). Not run by
    /// the Task Scheduler yet: a task with it is refused.
    After {
        task: String,
        #[serde(default)]
        only_on_success: bool,
    },
}

fn default_boot_delay() -> u32 {
    60
}

impl TaskTrigger {
    /// The task gets a `.timer` unit.
    pub fn has_timer(&self) -> bool {
        matches!(
            self,
            TaskTrigger::Calendar { .. } | TaskTrigger::Recurrence { .. } | TaskTrigger::Boot { .. }
        )
    }

    /// The `OnCalendar=` expression of a calendar or preset trigger (`None` for a preset that
    /// is not one valid expression).
    pub fn on_calendar(&self) -> Option<String> {
        match self {
            TaskTrigger::Calendar { on_calendar, .. } => Some(on_calendar.clone()),
            TaskTrigger::Recurrence { recurrence } => recurrence.to_calendar().ok(),
            _ => None,
        }
    }

    /// The Task Scheduler can run it today (the other kinds come with the scheduling gate).
    pub fn runnable(&self) -> bool {
        !matches!(
            self,
            TaskTrigger::Interval { .. } | TaskTrigger::Window { .. } | TaskTrigger::After { .. }
        )
    }
}

/// When a finished run sends a notification.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum NotifyPolicy {
    Never,
    #[default]
    OnFailure,
    Always,
}

/// `GET /api/v1/scheduler/tasks[/{id}]`: a task as the session user sees it (its staged
/// version if any) with the system state.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct TaskView {
    pub task: ScheduledTask,
    pub status: TaskStatus,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct TaskStatus {
    /// What the user's pending changeset does to this task.
    #[serde(default)]
    pub pending: Option<PendingOp>,
    /// The task is in the applied configuration (its units exist).
    pub applied: bool,
    /// `rynas-task-<id>.service`.
    pub unit: String,
    /// The service is running now.
    pub running: bool,
    /// Next start of the timer.
    #[serde(default)]
    pub next_run_ms: Option<u64>,
    /// Latest recorded run.
    #[serde(default)]
    pub last_run: Option<TaskRun>,
    /// The task is paused on its own (its starts are skipped until it is resumed); a pause of
    /// every task is in [`SchedulerPause::all`].
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub paused: Option<PauseInfo>,
    /// A failed run will be tried again.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub retry: Option<PendingRetry>,
}

/// A pause of the scheduled starts (`POST /api/v1/scheduler/pause`, or
/// `.../tasks/{id}/pause`): the scheduling gate skips them, recorded with reason `paused`.
/// "Run now" still runs.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct PauseInfo {
    pub since_ms: u64,
    /// Resumes by itself then; `None`: until resumed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub until_ms: Option<u64>,
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub reason: String,
    /// Who paused.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub by: String,
}

impl PauseInfo {
    /// Still in force at `now_ms`.
    pub fn active(&self, now_ms: u64) -> bool {
        self.until_ms.is_none_or(|u| now_ms < u)
    }
}

/// `GET /api/v1/scheduler/pause`: the pauses in force.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SchedulerPause {
    /// Every task is paused.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub all: Option<PauseInfo>,
    /// Tasks paused one by one.
    #[serde(default, skip_serializing_if = "std::collections::BTreeMap::is_empty")]
    pub tasks: std::collections::BTreeMap<String, PauseInfo>,
}

impl SchedulerPause {
    /// Drops the pauses that ended before `now_ms`; `true` when something changed.
    pub fn expire(&mut self, now_ms: u64) -> bool {
        let before = (self.all.is_some(), self.tasks.len());
        if self.all.as_ref().is_some_and(|p| !p.active(now_ms)) {
            self.all = None;
        }
        self.tasks.retain(|_, p| p.active(now_ms));
        before != (self.all.is_some(), self.tasks.len())
    }

    /// Why a scheduled start of `task` is skipped at `now_ms`, if it is.
    pub fn blocks(&self, task: &str, now_ms: u64) -> Option<SkipReason> {
        if self.all.as_ref().is_some_and(|p| p.active(now_ms)) {
            return Some(SkipReason::PausedAll);
        }
        self.tasks
            .get(task)
            .filter(|p| p.active(now_ms))
            .map(|_| SkipReason::Paused)
    }
}

/// Body of `POST /api/v1/scheduler/pause` and `.../tasks/{id}/pause`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct PauseRequest {
    /// Resume by itself then (ms since the epoch, in the future); absent: until resumed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub until_ms: Option<u64>,
    /// Shown with the pause (at most 200 characters).
    #[serde(default)]
    pub reason: String,
}

/// A retry armed after a failed run.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct PendingRetry {
    /// The retry that comes next (1 = first).
    pub attempt: u8,
    /// Retries the policy allows.
    pub attempts: u8,
    pub due_ms: u64,
}

/// How a recorded start came about.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RunTrigger {
    /// Its timer, on schedule.
    Timer,
    /// Its timer, catching up a run missed while the NAS was off.
    CatchUp,
    /// Its timer after boot (boot trigger).
    Boot,
    /// Run now.
    Manual,
    /// A retry after a failed run.
    Retry,
    /// Its timer fired while the previous run was still going: started when it ended
    /// (overlap policy `queue`).
    Queued,
    /// Started outside rynas (`systemctl start`).
    Other,
}

/// Why a start was skipped (a recorded outcome, not a run).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SkipReason {
    /// Every task was paused.
    PausedAll,
    /// This task was paused.
    Paused,
    /// A run missed while the NAS was off, past the catch-up deadline.
    Missed,
    /// Its time came while the previous run was still going (overlap policy `skip`).
    Overlap,
    /// The previous run of the task is still going in rynas.
    Running,
}

/// One recorded run (from the `ExecStopPost` hook).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct TaskRun {
    /// Increasing id of the record.
    pub id: u64,
    pub task_id: String,
    /// systemd invocation id of the run.
    pub invocation_id: String,
    #[serde(default)]
    pub start_ms: Option<u64>,
    pub end_ms: u64,
    /// systemd's `$SERVICE_RESULT`: `success`, `exit-code`, `signal`, `timeout`, `core-dump`...
    pub result: String,
    /// Exit status of the main process (`None` when it was killed by a signal).
    #[serde(default)]
    pub exit_code: Option<i32>,
    /// Signal name when it was killed (`TERM`, `KILL`).
    #[serde(default)]
    pub signal: Option<String>,
    pub ok: bool,
    /// Bytes of output kept (the last 256 KiB).
    pub output_bytes: u64,
    /// The output was longer than what is kept.
    pub output_truncated: bool,
    /// The output itself: only in `GET .../history/{n}`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub output: Option<String>,
    /// How it started (absent in runs recorded before the scheduling gate).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trigger: Option<RunTrigger>,
    /// The start did not run: why. Then `ok` is false and `result` is `skipped`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub skipped: Option<SkipReason>,
    /// Retry number of this run (1 = the first retry); 0 for a normal run.
    #[serde(default, skip_serializing_if = "is_zero")]
    pub attempt: u8,
    /// A detail of the outcome (the reason of a pause, the deadline of a missed run).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
    /// rynas could not be asked when it started: it ran as it would have before the
    /// scheduling gate.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub ungated: bool,
}

fn is_zero(n: &u8) -> bool {
    *n == 0
}

/// Live output of the running invocation (`GET /api/v1/scheduler/tasks/{id}/live`, SSE):
/// first event `run`, data [`LiveRun`].
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct LiveRun {
    /// systemd invocation id of the run being followed.
    pub invocation_id: String,
    #[serde(default)]
    pub start_ms: Option<u64>,
}

/// Last event of a live output stream (`end`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct LiveEnd {
    /// `false`: nothing was running when the stream opened.
    pub ran: bool,
}

/// Event names of the live output stream. `lines` carries a JSON array of strings: one
/// journal entry each (one output line without its newline, carriage returns kept, bytes
/// that are not UTF-8 replaced by U+FFFD).
pub mod live_event {
    pub const RUN: &str = "run";
    pub const LINES: &str = "lines";
    pub const END: &str = "end";
    /// The journal could not be read (data `{"message": …}`); the stream ends after it.
    /// (Not `error`: that name is the browser's own connection error event.)
    pub const FAILED: &str = "failed";
}

/// `POST /api/v1/scheduler/tasks/preview-calendar`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CalendarPreviewRequest {
    pub expression: String,
    #[serde(default)]
    pub syntax: CalendarSyntax,
    /// Number of next runs to compute (default 5, at most 20).
    #[serde(default)]
    pub count: Option<u32>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum CalendarSyntax {
    /// systemd `OnCalendar=`.
    #[default]
    Calendar,
    /// Five-field crontab line (`m h dom mon dow`) or `@daily`-style shortcut.
    Cron,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct CalendarPreview {
    pub valid: bool,
    /// The `OnCalendar=` expression to store (converted from cron if needed).
    #[serde(default)]
    pub on_calendar: String,
    /// systemd's normalized form.
    #[serde(default)]
    pub normalized: String,
    /// Next runs.
    #[serde(default)]
    pub next_ms: Vec<u64>,
    #[serde(default)]
    pub error: Option<String>,
}

/// `POST /api/v1/scheduler/preview`: a schedule as the NAS will run it. Give `expression`
/// (an `OnCalendar=` expression, or a crontab line with `syntax: cron`) or `trigger`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SchedulePreviewRequest {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expression: Option<String>,
    #[serde(default)]
    pub syntax: CalendarSyntax,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trigger: Option<TaskTrigger>,
    /// IANA time zone; default the NAS's.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tz: Option<String>,
    /// Number of next runs (default 5, at most 20).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub count: Option<u32>,
}

/// Answer of `POST /api/v1/scheduler/preview` (always 200; `valid: false` with `error`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SchedulePreview {
    pub valid: bool,
    /// The time zone of the runs (IANA name; empty when the NAS's zone has none).
    #[serde(default)]
    pub tz: String,
    /// The `OnCalendar=` expression to store (from cron or a preset), for calendar triggers.
    #[serde(default)]
    pub on_calendar: String,
    /// systemd's normalized form of it.
    #[serde(default)]
    pub normalized: String,
    /// The preset the expression is, if any: the structured description the interface puts
    /// into words; `None` with `normalized` set: an advanced expression.
    #[serde(default)]
    pub preset: Option<Recurrence>,
    /// Next runs.
    #[serde(default)]
    pub runs: Vec<PreviewRun>,
    /// A valid schedule that systemd will never start again: a date in the past, or an
    /// expression systemd gives up on around a DST change at midnight (the timer would stay
    /// without a next run).
    #[serde(default)]
    pub no_next_run: bool,
    /// The expression has no end but systemd stops scheduling it within the next year (at a
    /// DST change at midnight): after its last run the timer has no next run.
    #[serde(default)]
    pub stops: bool,
    /// When `stops`: the local date (`YYYY-MM-DD`) of the change where it stops.
    #[serde(default)]
    pub stops_on: Option<String>,
    /// Clock changes in the next year that change when the schedule runs.
    #[serde(default)]
    pub dst: Vec<DstNote>,
    #[serde(default)]
    pub error: Option<String>,
}

/// One next run.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct PreviewRun {
    pub ms: u64,
    /// Wall-clock time in the preview's zone, `YYYY-MM-DD HH:MM:SS`.
    pub local: String,
    /// Zone abbreviation at that moment (`CET`, `CEST`), empty when the zone has none.
    #[serde(default)]
    pub abbreviation: String,
    /// Seconds east of UTC at that moment.
    pub offset_s: i32,
}

/// A clock change that affects a schedule: on `date` the clocks jump from `from` to `to`
/// (local times, `HH:MM`). Forward: the schedule's times in between do not exist that day and
/// are skipped. Back: its times in between exist twice and run once (the first time).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct DstNote {
    /// The moment of the change.
    pub ms: u64,
    /// `YYYY-MM-DD`, local.
    pub date: String,
    pub forward: bool,
    pub from: String,
    pub to: String,
}

/// `GET /api/v1/scheduler/system-timers`: systemd timers not generated by rynas (read-only).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SystemTimer {
    pub unit: String,
    pub activates: String,
    #[serde(default)]
    pub next_ms: Option<u64>,
    #[serde(default)]
    pub last_ms: Option<u64>,
    /// `OnCalendar=` expressions of the timer, if any.
    #[serde(default)]
    pub on_calendar: Vec<String>,
}

/// `GET /api/v1/scheduler/cron-entries`: crontab lines found on the system (read-only).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct CronEntry {
    /// `/etc/crontab`, `/etc/cron.d/<name>` or `/var/spool/cron/crontabs/<user>`.
    pub source: String,
    pub line: u32,
    /// The five time fields or the `@` shortcut.
    pub schedule: String,
    pub user: String,
    pub command: String,
    /// The equivalent trigger, when there is one (`@reboot` is a boot trigger).
    #[serde(default)]
    pub trigger: Option<TaskTrigger>,
}
